package net.battlespades.bot;
import java.io.*;
import java.math.BigInteger;
import java.nio.charset.StandardCharsets;
import java.util.*;
import net.battlespades.physics.PlayerPhysics.Vector;
import net.battlespades.player.SourceRandom;
import net.battlespades.world.MetadataDocument;
import net.battlespades.bot.BotState.Observer;
import static net.battlespades.bot.BotState.*;
import org.junit.jupiter.api.Test;
import static org.junit.jupiter.api.Assertions.*;
class BotFoundationsTest {
    @SuppressWarnings("unchecked") static Map<String,Object> map(Object value){return (Map<String,Object>)value;}
    static List<?> list(Object value){return (List<?>)value;}static int integer(Object value){return ((Number)value).intValue();}static long number(Object value){return ((Number)value).longValue();}static double real(Object value){return ((Number)value).doubleValue();}static boolean bool(Object value){return Boolean.TRUE.equals(value);}static String string(Object value){return (String)value;}
    static final Map<String,Object> FIXTURE=read();private static Map<String,Object> read(){try(var stream=Objects.requireNonNull(BotFoundationsTest.class.getResourceAsStream("/golden/bot-foundations.json"))){return map(MetadataDocument.json(new String(stream.readAllBytes(),StandardCharsets.UTF_8)));}catch(IOException failure){throw new UncheckedIOException(failure);}}
    static Vector vector(Object value){var a=list(value);return new Vector(real(a.get(0)),real(a.get(1)),real(a.get(2)));}static Cell cell(Object value){var a=list(value);return new Cell(integer(a.get(0)),integer(a.get(1)),integer(a.get(2)));}static Observer observer(Object value){var a=list(value);return new Observer(integer(a.get(0)),integer(a.get(1)));}
    static Object data(Object value){if(value instanceof Vector p)return List.of(p.x(),p.y(),p.z());if(value instanceof Enum<?> e)return e.name().toLowerCase(Locale.ROOT);if(value instanceof Record r){var result=new LinkedHashMap<String,Object>();try{for(var c:r.getClass().getRecordComponents())result.put(c.getName().replaceAll("([a-z0-9])([A-Z])","$1_$2").toLowerCase(Locale.ROOT),data(c.getAccessor().invoke(r)));}catch(ReflectiveOperationException error){throw new IllegalStateException(error);}return result;}if(value instanceof Map<?,?> m){var result=new LinkedHashMap<String,Object>();m.forEach((k,v)->result.put(k.toString(),data(v)));return result;}if(value instanceof Collection<?> c)return c.stream().map(BotFoundationsTest::data).toList();return value;}
    static void equal(Object expected,Object actual){actual=data(actual);if(expected instanceof Number a&&actual instanceof Number b){assertEquals(a.doubleValue(),b.doubleValue(),Math.max(1e-12,Math.abs(a.doubleValue())*1e-12));return;}if(expected instanceof Map<?,?> a&&actual instanceof Map<?,?> b){assertEquals(a.keySet(),b.keySet());for(var key:a.keySet())equal(a.get(key),b.get(key));return;}if(expected instanceof List<?> a&&actual instanceof List<?> b){assertEquals(a.size(),b.size());for(int i=0;i<a.size();i++)equal(a.get(i),b.get(i));return;}assertEquals(expected,actual);}
    static BotProfile profile(Object value){var p=map(value);return new BotProfile(string(p.get("name")),string(p.get("difficulty")),real(p.get("skill")),real(p.get("aggression")),real(p.get("caution")),real(p.get("teamwork")),real(p.get("creativity")),real(p.get("reaction_time")),real(p.get("tracking_delay")),real(p.get("turn_speed")),real(p.get("turn_acceleration")),real(p.get("recoil_control")),real(p.get("burst_discipline")),real(p.get("preferred_range")),real(p.get("aim_noise")),list(p.get("class_preferences")).stream().map(BotFoundationsTest::integer).toList());}
    @Test void deterministicProfilesRetainBothSourceStreamsAcrossNameReleaseAndTightWireLimits(){for(var value:list(FIXTURE.get("profiles"))){var row=map(value);var factory=new BotProfileFactory(new BigInteger(string(row.get("seed"))),integer(row.get("length")));for(var action:list(row.get("commands"))){var command=map(action);if(command.get("op").equals("release"))factory.release(string(command.get("name")));else equal(command.get("result"),factory.create(string(command.get("difficulty"))));}}}
    @Test void planningFairnessCreditsRefundsExpiryPreviewAndBoundedSamplesMatchTheOriginal(){for(var value:list(FIXTURE.get("budgets"))){var row=map(value);var budget=new PlanningBudget(real(row.get("rate")),real(row.get("frequency")));var jobs=new HashMap<Integer,PlanningBudget.Job>();for(var action:list(row.get("commands"))){var c=map(action);switch(string(c.get("op"))){case "acquire"->{var key=observer(c.get("key"));double now=real(c.get("now"));equal(c.get("preview"),List.of(budget.wouldGrant(key,now),budget.spare(key,now)));var job=budget.acquire(key,now);equal(c.get("answer"),job!=null);if(job!=null)jobs.put(integer(c.get("job")),job);}case "finish"->{var job=jobs.get(integer(c.get("job")));var maxima=list(c.get("maxima"));var grants=list(c.get("grants"));var used=list(c.get("used"));for(int i=0;i<maxima.size();i++){assertEquals(integer(grants.get(i)),job.beginSearch(integer(maxima.get(i))));job.expansions(job.expansions()+integer(used.get(i)));}assertEquals(integer(c.get("expansions")),job.expansions());budget.finish(job,real(c.get("seconds")));}case "scale"->budget.scaleFor(integer(c.get("bots")));case "refresh"->budget.refreshWaiters(list(c.get("keys")).stream().map(BotFoundationsTest::observer).toList(),real(c.get("now")));case "cancel"->budget.cancel(observer(c.get("key")));case "reset"->budget.reset();case "flood"->{for(int i=0;i<integer(c.get("count"));i++)budget.acquire(new Observer(i,9),real(c.get("now")));}case "raw_samples"->{for(int i=0;i<integer(c.get("count"));i++){var job=new PlanningBudget.Job();job.beginSearch(512);job.expansions(7);budget.finish(job,i/1000.);}}default->fail("Unknown budget command");}assertEquals(c.get("denial"),budget.lastDenial());equal(c.get("snapshot"),budget.snapshot());}}}
    @Test void hearingMatchesSourceUncertaintyExpirationOwnNoiseFootstepCadenceAndCapacity(){var bus=new BotStimulusBus(4);var random=new SourceRandom(123);for(var value:list(FIXTURE.get("sounds"))){var c=map(value);Object actual=switch(string(c.get("op"))){case "publish"->bus.publish(StimulusKind.valueOf(string(c.get("kind")).toUpperCase(Locale.ROOT)),vector(c.get("at")),integer(c.get("source")),integer(c.get("team")),real(c.get("radius")),real(c.get("lifetime")),real(c.get("now")));case "bad_position"->bus.publish(StimulusKind.SHOT,null,-1,-1,64,1.5,2);case "perceive"->bus.perceive(vector(c.get("at")),real(c.get("now")),random,integer(c.get("limit")),integer(c.get("observer")),c.get("team")==null?null:integer(c.get("team")));case "footsteps"->{var players=new ArrayList<FootstepPlayer>();for(var item:list(c.get("players"))){var p=map(item);players.add(new FootstepPlayer(integer(p.get("id")),integer(p.get("team")),bool(p.get("alive")),bool(p.get("spawned")),bool(p.get("grounded")),bool(p.get("crouch")),bool(p.get("sneak")),bool(p.get("sprint")),vector(p.get("velocity")),vector(p.get("position"))));}yield bus.footsteps(players,real(c.get("now")));}case "capacity"->{for(int i=0;i<40;i++)bus.publish(StimulusKind.OBJECTIVE,new Vector(i,0,0),i+100,-1,256,1.5,20+i*.1);yield bus.perceive(new Vector(0,0,0),24,random,50,-1,null);}default->throw new IllegalArgumentException("Unknown sensory command");};equal(c.get("result"),actual);}}
    @Test void adaptiveDifficultyUsesOriginalBasesTeamChangesGenerationFencesAndDisabledRecovery(){for(var value:list(FIXTURE.get("scales"))){var r=map(value);equal(r.get("result"),BotSkillBalancer.scale(profile(r.get("profile")),real(r.get("strength")),BotSkillBalancer.limits(list(r.get("bands")).stream().map(BotFoundationsTest::string).toList())));}var balance=new BotSkillBalancer();var fixture=map(FIXTURE.get("balancing"));for(var value:list(fixture.get("steps"))){var s=map(value);var humans=list(s.get("humans")).stream().map(v->{var p=map(v);return new BotSkillBalancer.Human(integer(p.get("team")),number(p.get("kills")),number(p.get("deaths")),bool(p.get("bot")));}).toList();var scores=new HashMap<Integer,Double>();map(s.get("scores")).forEach((k,v)->scores.put(Integer.parseInt(k),real(v)));var bots=list(s.get("before")).stream().map(v->{var b=map(v);return new BotSkillBalancer.Bot(new Observer(integer(b.get("id")),integer(b.get("generation"))),integer(b.get("team")),profile(b.get("profile")));}).toList();var roster=new BotSkillBalancer.Roster(humans,scores,true,bool(s.get("ended")));var result=balance.update(real(s.get("now")),roster,bots,new BotSkillBalancer.Settings(bool(s.get("enabled")),"normal",.03,.35,6,.15));equal(s.get("factors"),balance.factors());equal(s.get("targets"),balance.targets());for(var b:bots)equal(map(s.get("after")).get(Integer.toString(b.observer().playerId())),result.get(b.observer()));}}
    @Test void atlasPlanesWaterFlowsContextsAndSourceCacheEnvelopesMatch()throws Exception{for(var value:list(FIXTURE.get("digests"))){var row=map(value);assertEquals(row.get("digest"),HexFormat.of().formatHex(NavigationAtlas.sourceDigest(HexFormat.of().parseHex(string(row.get("raw"))))));}for(var value:list(FIXTURE.get("atlases"))){var row=map(value);var masks=list(row.get("masks")).stream().map(v->new BigInteger(string(v).substring(2),16)).toList();var atlas=NavigationAtlas.build(integer(row.get("width")),integer(row.get("height")),integer(row.get("water")),(col,word)->masks.get(col).shiftRight(word*64).longValue());atlas.validate();assertAtlas(row,atlas);byte[] digest=HexFormat.of().parseHex(string(row.get("digest"))),bytes=Base64.getDecoder().decode(string(row.get("cache")));assertAtlas(row,NavigationAtlas.decode(bytes,digest));assertAtlas(row,NavigationAtlas.decode(atlas.encode(digest),digest));var wrong=digest.clone();wrong[0]^=1;assertThrows(IllegalArgumentException.class,()->NavigationAtlas.decode(bytes,wrong));var trailing=Arrays.copyOf(bytes,bytes.length+1);assertThrows(IllegalArgumentException.class,()->NavigationAtlas.decode(trailing,digest));}for(var value:list(FIXTURE.get("bad_caches"))){var row=map(value);byte[] bytes=Base64.getDecoder().decode(string(row.get("cache"))),digest=HexFormat.of().parseHex(string(row.get("digest")));assertThrows(IllegalArgumentException.class,()->NavigationAtlas.decode(bytes,digest),string(row.get("label")));}}
    private static void assertAtlas(Map<String,Object> row,NavigationAtlas atlas){equal(row.get("stats"),atlas.stats());var planes=map(row.get("planes"));for(int i=0;i<atlas.area();i++){assertEquals(integer(list(planes.get("primary_support")).get(i)),atlas.primary(i));assertEquals(integer(list(planes.get("layer_count")).get(i)),atlas.layerCount(i));assertEquals(integer(list(planes.get("flags")).get(i)),atlas.flags(i));assertEquals(integer(list(planes.get("clearance")).get(i)),atlas.clearance(i));assertEquals(integer(list(planes.get("regions")).get(i)),atlas.region(i));assertEquals(integer(list(planes.get("water_next")).get(i)),atlas.next(i));assertEquals(integer(list(planes.get("water_goal")).get(i)),atlas.goal(i));assertEquals(integer(list(planes.get("water_distance")).get(i)),atlas.distance(i));equal(list(row.get("contexts")).get(i),atlas.context(i%atlas.width(),i/atlas.width(),30));equal(list(row.get("routes")).get(i),atlas.waterRoute(i%atlas.width(),i/atlas.width()));}}
}
